  # Write your code here
}

solution:
net_single_premium <- function(sum_assured, age, mortality_table, interest_rate, term) {
  nsp <- 0
  survival <- 1
  for (k in seq_len(term) - 1) {
    q <- mortality_table[[as.character(age + k)]]
    nsp <- nsp + sum_assured * survival * q / (1 + interest_rate)^(k + 1)
    survival <- survival * (1 - q)
  }
  nsp
}

