starterCode:
irr <- function(cash_flows, initial_guess) {
  # Write your code here
}

solution:
irr <- function(cash_flows, initial_guess) {
  times <- seq_along(cash_flows) - 1
  rate <- initial_guess
  for (iter in 1:100) {
    npv <- sum(cash_flows / (1 + rate)^times)
    slope <- sum(-times * cash_flows / (1 + rate)^(times + 1))
    step <- npv / slope
    rate <- rate - step
    if (abs(step) < 1e-10) break
  }
  rate
}

